import wagtail_color_panel.fields
from django.db import migrations, models


def keep_custom_navbars(apps, schema_editor):
    """Les sites dont la barre n'était pas aux couleurs principales gardent leurs couleurs."""
    ThemeSettings = apps.get_model("core", "ThemeSettings")
    for theme in ThemeSettings.objects.all():
        follows = (
            theme.navbar_bg.lower() == theme.primary_color.lower()
            and theme.navbar_text.lower() == "#ffffff"
        )
        if not follows:
            theme.navbar_follows_primary = False
            theme.save(update_fields=["navbar_follows_primary"])


